<?php
require_once __DIR__ . '/includes/auth.php'; requireLogin();
$pdo=db();$uid=userId();$pageTitle='Budget';$activePage='budget.php';$month=(int)($_GET['month']??date('m'));$year=(int)($_GET['year']??date('Y'));
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$action=$_POST['action']??'';if($action==='delete'){$st=$pdo->prepare('DELETE FROM budgets WHERE id=? AND user_id=?');$st->execute([(int)$_POST['id'],$uid]);flash('success','Budget berhasil dihapus.');redirect('budget.php');}if($action==='save'){$id=(int)($_POST['id']??0);$category=trim((string)$_POST['category']);$amount=parseAmount($_POST['amount']??0);$m=(int)$_POST['month'];$y=(int)$_POST['year'];if($category===''||$amount<=0||$m<1||$m>12||$y<2020){flash('error','Lengkapi kategori, nominal, dan periode budget dengan benar.');redirect('budget.php?action='.($id?'edit&id='.$id:'add'));}if($id){$st=$pdo->prepare('UPDATE budgets SET category=?,amount=?,month=?,year=? WHERE id=? AND user_id=?');$st->execute([$category,$amount,$m,$y,$id,$uid]);}else{$st=$pdo->prepare('INSERT INTO budgets(user_id,category,amount,month,year) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE amount=VALUES(amount)');$st->execute([$uid,$category,$amount,$m,$y]);}flash('success','Budget berhasil disimpan.');redirect('budget.php?month='.$m.'&year='.$y);}}
$st=$pdo->prepare('SELECT b.*,COALESCE((SELECT SUM(t.amount) FROM transactions t WHERE t.user_id=b.user_id AND t.type="expense" AND t.category=b.category AND t.transaction_date BETWEEN CONCAT(b.year,"-",LPAD(b.month,2,"0"),"-01") AND LAST_DAY(CONCAT(b.year,"-",LPAD(b.month,2,"0"),"-01"))),0) used_amount FROM budgets b WHERE b.user_id=? AND b.month=? AND b.year=? ORDER BY b.category');$st->execute([$uid,$month,$year]);$rows=$st->fetchAll();$edit=null;if(($_GET['action']??'')==='edit'){$st=$pdo->prepare('SELECT * FROM budgets WHERE id=? AND user_id=?');$st->execute([(int)$_GET['id'],$uid]);$edit=$st->fetch()?:null;}if(($_GET['action']??'')==='add')$edit=['id'=>0,'category'=>'','amount'=>'','month'=>$month,'year'=>$year];$categories=['Makanan','Minuman','Transportasi','Bensin','Parkir','Tagihan','Belanja','Hiburan','Gaming','Kesehatan','Pendidikan','Rumah Tangga','Pulsa/Internet','Fashion','Nongkrong','Travel','Pengeluaran Lainnya'];$user=currentUser($pdo);require __DIR__.'/includes/header.php';
?>
<div class="page-heading"><div><p class="eyebrow">Rencana pengeluaran</p><h1>Budget Bulanan</h1><p>Atur batas pengeluaran per kategori dan pantau progresnya.</p></div><a class="btn btn-primary" href="?action=add"><i data-lucide="plus"></i> Tambah Budget</a></div>
<form class="toolbar glass-card" method="get"><div class="toolbar-form"><input class="input" type="month" name="period" value="<?= e(sprintf('%04d-%02d',$year,$month)) ?>" onchange="this.form.month.value=this.value.split('-')[1];this.form.year.value=this.value.split('-')[0]"><input type="hidden" name="month" value="<?= $month ?>"><input type="hidden" name="year" value="<?= $year ?>"><button class="btn btn-soft" type="submit"><i data-lucide="calendar-range"></i> Tampilkan</button></div></form>
<section class="card"><div class="card-header"><div><h2 class="card-title">Budget <?= e(date('F Y',strtotime(sprintf('%04d-%02d-01',$year,$month)))) ?></h2><p class="card-subtitle">Status Aman di bawah 70%, Mendekati Batas 70–100%.</p></div></div><?php if(!$rows): ?><div class="empty-state"><div class="empty-icon"><i data-lucide="wallet-cards"></i></div><strong>Belum ada budget.</strong><p>Buat batas pengeluaran supaya keputusan harian lebih terarah.</p><a class="btn btn-primary btn-sm" href="?action=add">Tambah Budget</a></div><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Kategori</th><th>Budget</th><th>Terpakai</th><th>Sisa</th><th>Progress</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $row):[$label,$tone,$percent]=statusBudget((float)$row['used_amount'],(float)$row['amount']);$remaining=(float)$row['amount']-(float)$row['used_amount'];?><tr><td><strong><?= e($row['category']) ?></strong></td><td><?= formatRupiah($row['amount']) ?></td><td><?= formatRupiah($row['used_amount']) ?></td><td class="<?= $remaining<0?'negative':'positive' ?>"><?= formatRupiah($remaining) ?></td><td style="min-width:150px"><div class="progress-line"><div class="progress-fill <?= e($tone) ?>" style="width:<?= $percent ?>%"></div></div><small class="form-hint"><?= number_format($percent,1,',','.') ?>%</small></td><td><span class="badge <?= e($tone) ?>"><?= e($label) ?></span></td><td><div class="actions"><a class="btn btn-ghost btn-sm icon-btn" href="?action=edit&id=<?= (int)$row['id'] ?>"><i data-lucide="pencil"></i></a><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="btn btn-ghost btn-sm icon-btn" data-confirm="Hapus budget ini?" type="submit"><i data-lucide="trash-2"></i></button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<div class="modal <?= $edit?'is-open':'' ?>" id="budget-modal"><div class="modal-head"><div><h3><?= $edit&&$edit['id']?'Edit':'Tambah' ?> Budget</h3><p>Budget berlaku untuk satu kategori dan satu bulan.</p></div><button class="icon-button" data-close-modal type="button"><i data-lucide="x"></i></button></div><form method="post" data-amount-form><input type="hidden" name="csrf_token" value="<?= e(csrfToken()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div class="form-grid"><div class="form-field"><label>Kategori</label><input class="input" name="category" list="budget-cats" value="<?= e($edit['category']??'') ?>" required><datalist id="budget-cats"><?php foreach($categories as $cat):?><option value="<?=e($cat)?>"><?php endforeach;?></datalist></div><div class="form-field"><label>Nominal</label><input class="input" name="amount" data-amount value="<?= e($edit['amount']??'') ?>" required></div><div class="form-field"><label>Bulan</label><select class="select" name="month"><?php for($i=1;$i<=12;$i++):?><option value="<?=$i?>" <?=$i==(int)($edit['month']??$month)?'selected':''?>><?=e(date('F',mktime(0,0,0,$i,1)))?></option><?php endfor;?></select></div><div class="form-field"><label>Tahun</label><input class="input" type="number" name="year" min="2020" max="2100" value="<?=e($edit['year']??$year)?>"></div></div><div class="modal-actions"><button class="btn btn-ghost" data-close-modal type="button">Batal</button><button class="btn btn-primary" type="submit">Simpan Budget</button></div></form></div>
<?php require __DIR__.'/includes/footer.php'; ?>